<?php

declare(strict_types=1);

require_once __DIR__.'/../../../../config/database.php';require_once __DIR__.'/../../../../app/Http/JsonResponse.php';require_once __DIR__.'/../../../../app/Http/Request.php';require_once __DIR__.'/../../../../app/Auth/Authorization.php';require_once __DIR__.'/../../../../app/Auth/ApiAuth.php';require_once __DIR__.'/../../../../app/Support/Validation.php';require_once __DIR__.'/../../../../app/Reports/ReportUpload.php';require_once __DIR__.'/../../../../app/Audit/AuditLogger.php';

floodguardRequireMethod('GET','POST');$permission=$_SERVER['REQUEST_METHOD']==='POST'?'reports.create_own':'reports.view_own';$user=floodguardRequireApiUser($pdo,$permission);$userId=(int)$user['id'];
try{
if($_SERVER['REQUEST_METHOD']==='GET'){$stmt=$pdo->prepare('SELECT id,report_number,location_description,immediate_danger,status,submitted_at,reviewed_at,decision_reason,updated_at FROM flood_reports WHERE reporter_user_id=:user_id ORDER BY submitted_at DESC,id DESC LIMIT 100');$stmt->execute([':user_id'=>$userId]);floodguardJsonResponse(200,['success'=>true,'data'=>$stmt->fetchAll()]);}
$count=$pdo->prepare('SELECT COUNT(*) FROM flood_reports WHERE reporter_user_id=:user_id AND submitted_at>=DATE_SUB(NOW(),INTERVAL 1 HOUR)');$count->execute([':user_id'=>$userId]);$maximum=(int)($pdo->query("SELECT setting_value FROM system_settings WHERE setting_key='resident_report_rate_limit_per_hour' LIMIT 1")->fetchColumn()?:5);if((int)$count->fetchColumn()>=max(1,$maximum))floodguardJsonResponse(429,['success'=>false,'message'=>'Flood-report submission limit reached. Try again later.']);
$location=floodguardRequiredString($_POST,'location_description',500);$description=floodguardRequiredString($_POST,'flood_description',5000);[$latitude,$longitude]=floodguardReportCoordinates($_POST);$danger=filter_var($_POST['immediate_danger']??false,FILTER_VALIDATE_BOOLEAN);$photo=floodguardValidateReportPhoto($pdo,$_FILES['photo']??[]);
$profile=$pdo->prepare('SELECT mobile_number FROM resident_profiles WHERE user_id=:id');$profile->execute([':id'=>$userId]);$mobile=$profile->fetchColumn();if(!$mobile)floodguardJsonResponse(409,['success'=>false,'message'=>'Complete your resident profile before submitting a report.']);
$number='FG-RPT-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$stored=null;$pdo->beginTransaction();
$stmt=$pdo->prepare('INSERT INTO flood_reports (report_number,reporter_user_id,reporter_name_snapshot,reporter_phone_snapshot,location_description,latitude,longitude,flood_description,immediate_danger,status,submitted_at) VALUES (:number,:user_id,:name,:phone,:location,:lat,:lng,:description,:danger,"submitted",NOW())');$stmt->execute([':number'=>$number,':user_id'=>$userId,':name'=>$user['full_name'],':phone'=>$mobile,':location'=>$location,':lat'=>$latitude,':lng'=>$longitude,':description'=>$description,':danger'=>(int)$danger]);$reportId=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO flood_report_revisions (flood_report_id,revision_number,location_description,latitude,longitude,flood_description,immediate_danger,submitted_by,submitted_at) VALUES (:id,1,:location,:lat,:lng,:description,:danger,:user_id,NOW())')->execute([':id'=>$reportId,':location'=>$location,':lat'=>$latitude,':lng'=>$longitude,':description'=>$description,':danger'=>(int)$danger,':user_id'=>$userId]);
$stored=floodguardStoreReportPhoto($photo);$pdo->prepare('INSERT INTO flood_report_photos (flood_report_id,storage_path,original_name,mime_type,file_size_bytes,sha256_hash,uploaded_by) VALUES (:report,:path,:name,:mime,:size,:hash,:user)')->execute([':report'=>$reportId,':path'=>$stored['storage_path'],':name'=>$photo['original_name'],':mime'=>$photo['mime_type'],':size'=>$photo['size'],':hash'=>$photo['sha256'],':user'=>$userId]);
$pdo->prepare('INSERT INTO flood_report_status_history (flood_report_id,from_status,to_status,changed_by,changed_at) VALUES (:report,NULL,"submitted",:user,NOW())')->execute([':report'=>$reportId,':user'=>$userId]);floodguardAudit($pdo,$userId,'flood_report.created','flood_report',$reportId,null,['report_number'=>$number,'status'=>'submitted','immediate_danger'=>$danger]);$pdo->commit();
floodguardJsonResponse(201,['success'=>true,'message'=>'Flood report submitted for barangay review.','data'=>['id'=>$reportId,'report_number'=>$number,'status'=>'submitted']]);
}catch(InvalidArgumentException $e){if($pdo->inTransaction())$pdo->rollBack();floodguardJsonResponse(422,['success'=>false,'message'=>$e->getMessage()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if(isset($stored['absolute_path'])&&is_file($stored['absolute_path']))unlink($stored['absolute_path']);error_log('[Resident reports] '.$e->getMessage());floodguardJsonResponse(500,['success'=>false,'message'=>'Unable to process the flood report.']);}
